// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, FileArchiveIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { ASSETS, CAPTIONS, DONE, HINT, OPTIONS, PAGES, PICKED, SKIPPED } from './script'

const SKIP = PAGES.indexOf(SKIPPED)
const SHOWN = ASSETS.slice(0, 10)
const SLOTS = SHOWN.map((_, index) => ({
  left: 8 + ((index * 37) % 78),
  top: 18 + ((index * 53) % 70),
}))
const FEATURES = [
  { name: 'Login', passed: 12, failed: 0 },
  { name: 'Checkout', passed: 9, failed: 2 },
  { name: 'Search', passed: 15, failed: 0 },
  { name: 'Profile', passed: 7, failed: 0 },
]

const build: Build = ({
  tl,
  q,
  qa,
  step,
  final,
  move,
  click,
  type,
  count,
  fly,
  wait,
  cursorOut,
}) => {
  step(0)
  move('scan', { at: 0.2 })
  click('scan')
  tl.fromTo(
    qa('page-row'),
    { opacity: 0, x: 8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.08, ease: 'power3.out' },
    '<0.1',
  )
  tl.fromTo(q('selected'), { opacity: 0 }, { opacity: 1, duration: 0.2 }, '<')

  step(1, '+=0.4')
  move(`box-${SKIP}`)
  click(`box-${SKIP}`)
  tl.to(
    q(`box-${SKIP}`),
    {
      backgroundColor: 'rgba(255,255,255,0)',
      borderColor: 'var(--demo-tint-16)',
      duration: 0.15,
    },
    '<',
  )
  tl.to(q(`tick-${SKIP}`), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q(`page-row-${SKIP}`), { color: 'var(--demo-muted)', duration: 0.2 }, '<')
  count('selected-count', PICKED.length, { from: PAGES.length, at: '<', duration: 0.2 })

  step(2, '+=0.4')
  move('zip')
  click('zip')
  tl.fromTo(q('progress'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.25 }, '<')
  type('phase', `Downloading report pages · ${PICKED.length} of ${PICKED.length}`, {
    at: '<',
    speed: 0.01,
  })
  tl.fromTo(q('bar'), { scaleX: 0 }, { scaleX: 0.3, duration: 0.6 }, '<')
  cursorOut('<')
  tl.to(q('swirl'), { rotation: 900, duration: 4, ease: 'power1.inOut' }, '<')
  type(
    'phase',
    `Fetching styles, scripts, fonts and images · ${ASSETS.length} of ${ASSETS.length}`,
    { at: '>-3.2', speed: 0.008 },
  )
  SHOWN.forEach((_, index) => {
    fly(`asset-${index}`, `slot-${index}`, 'well', {
      at: index === 0 ? '<' : '<0.16',
      duration: 0.75,
      lift: 10,
      scale: 0.15,
    })
  })
  tl.to(qa('asset'), { opacity: 0, duration: 0.15, stagger: 0.16 }, '<-0.74')
  tl.to(q('bar'), { scaleX: 0.85, duration: 1.6, ease: 'none' }, '<')
  tl.to(q('well'), { scale: 1.15, duration: 0.15, yoyo: true, repeat: 3 }, '<0.4')

  step(3, '+=0.3')
  type('phase', 'Compressing everything into one ZIP…', { speed: 0.01 })
  tl.to(q('bar'), { scaleX: 1, duration: 0.6 }, '<')
  tl.to(q('well'), {
    backgroundColor: 'rgba(52,211,153,0.2)',
    borderColor: 'rgba(52,211,153,0.8)',
    duration: 0.3,
  })
  tl.fromTo(
    q('banner'),
    { opacity: 0, y: -8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
    '<',
  )
  type('phase', DONE, { at: '<', speed: 0.01 })
  final('+=0.3')
  wait(1.6)
}

function Report() {
  return (
    <div className="relative h-full bg-[#fafafa] px-4 pt-3 text-[#111]">
      <p className="text-[8.5px] font-semibold uppercase tracking-[0.2em] text-[#15803d]">
        Cucumber report
      </p>
      <h3 className="mt-1 text-[15px] font-bold tracking-tight">
        Nightly · {FEATURES.reduce((sum, item) => sum + item.passed + item.failed, 0)} scenarios
      </h3>
      <div className="mt-3 space-y-1.5">
        {FEATURES.map((feature) => {
          const total = feature.passed + feature.failed
          return (
            <div
              key={feature.name}
              className="rounded-md border border-black/5 bg-white p-2 shadow-sm"
            >
              <p className="flex justify-between text-[9.5px] font-medium">
                <span className="text-[#2563eb] underline">{feature.name}</span>
                <span className="text-[#666]">
                  {feature.passed}/{total}
                </span>
              </p>
              <div className="mt-1 flex h-1.5 overflow-hidden rounded-full">
                <span
                  className="bg-[#22c55e]"
                  style={{ width: `${Math.round((feature.passed / total) * 100)}%` }}
                />
                <span className="flex-1 bg-[#ef4444]" />
              </div>
            </div>
          )
        })}
      </div>
      {SLOTS.map((slot, index) => (
        <span
          key={index}
          data-d={`slot-${index}`}
          className="absolute size-1"
          style={{ left: `${slot.left}%`, top: `${slot.top}%` }}
        />
      ))}
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="HTML Bundle scanning a test report, choosing pages and pulling every asset into one offline ZIP"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://ci.northwind.app/reports/nightly/index.html"
        panelWidth={250}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2">
              <div className="flex gap-1">
                <span
                  data-d="scan"
                  className="rounded-md bg-[var(--accent)] px-2 py-1 text-[9px] font-medium text-canvas"
                >
                  Scan links
                </span>
                <span className="truncate rounded-md border border-line-strong px-2 py-1 text-[9px] text-ink-soft">
                  Download current page
                </span>
              </div>
              <div className="flex gap-2.5 text-[8.5px] text-ink-soft">
                {OPTIONS.map((option) => (
                  <span key={option} className="flex items-center gap-1">
                    <span className="flex size-2.5 items-center justify-center rounded-sm bg-[var(--accent)] text-canvas">
                      <CheckIcon className="size-2" strokeWidth={3} />
                    </span>
                    {option}
                  </span>
                ))}
              </div>
              <p className="truncate text-[8px] text-muted">{HINT}</p>
              <p data-d="selected" className="text-[8.5px] text-muted opacity-0">
                <span data-d="selected-count">{PAGES.length}</span> of {PAGES.length} selected
              </p>
              <div className="space-y-0.5">
                {PAGES.map((page, index) => (
                  <div
                    key={page}
                    data-d={`page-row page-row-${index}`}
                    className="flex h-[17px] items-center gap-1.5 rounded px-1 opacity-0"
                  >
                    <span
                      data-d={`box-${index}`}
                      className="flex size-2.5 items-center justify-center rounded-sm border border-[var(--accent)] bg-[var(--accent)] text-canvas"
                    >
                      <span data-d={`tick-${index}`}>
                        <CheckIcon className="size-2" strokeWidth={3} />
                      </span>
                    </span>
                    <span className="font-mono text-[9px] text-ink">{page}</span>
                  </div>
                ))}
              </div>
              <span
                data-d="zip"
                className="w-fit rounded-md bg-[var(--accent)] px-2.5 py-1 text-[9.5px] font-medium text-canvas"
              >
                Download ZIP
              </span>
              <div
                data-d="progress"
                className="flex items-center gap-2.5 rounded-lg border border-line bg-canvas/70 p-2 opacity-0"
              >
                <span
                  data-d="well"
                  className="relative flex size-11 shrink-0 items-center justify-center rounded-full border border-[var(--accent)]/50 bg-[var(--accent)]/10"
                >
                  <span
                    data-d="swirl"
                    className="absolute inset-0 rounded-full"
                    style={{
                      background:
                        'conic-gradient(from 0deg, rgba(56,189,248,0.5), rgba(56,189,248,0) 40%, rgba(56,189,248,0.5) 50%, rgba(56,189,248,0) 90%)',
                    }}
                  />
                  <FileArchiveIcon className="relative size-4 text-ink" />
                </span>
                <div className="min-w-0 flex-1">
                  <p
                    data-d="phase"
                    className="min-h-[24px] text-[8.5px] leading-snug text-ink-soft"
                  />
                  <div className="mt-1 h-1 overflow-hidden rounded-full bg-ink/10">
                    <div
                      data-d="bar"
                      className="h-full origin-left scale-x-0 rounded-full bg-[var(--accent)]"
                    />
                  </div>
                </div>
              </div>
              <p
                data-d="banner"
                className="absolute inset-x-2 top-1.5 rounded-md bg-emerald px-2 py-1 text-center text-[9.5px] font-medium text-canvas opacity-0"
              >
                ZIP saved to Downloads
              </p>
            </div>
          </div>
        }
      >
        <Report />
      </BrowserChrome>
      {SHOWN.map((asset, index) => (
        <span
          key={asset}
          data-d={`asset asset-${index}`}
          className="absolute left-0 top-0 z-30 whitespace-nowrap rounded-md border border-[var(--accent)]/50 bg-elevated px-1.5 py-0.5 font-mono text-[8.5px] text-ink opacity-0 shadow-lg"
        >
          {asset}
        </span>
      ))}
    </DemoStage>
  )
}
